# with a single shared factor (scale=1 unclipped, scale=5/norm clipped).
eps = 1e-6
ratios = []
def scalars(m):
    for name in ("W", "b", "Why", "by"):
        node = m[name]
        if isinstance(node[0], list):
            for k in range(len(node)):
                for j in range(len(node[0])):
                    yield name, k, j, node[k][j]
        else:
            for k in range(len(node)):
                yield name, k, None, node[k]

for name, k, j, old in list(scalars(m0)):
    mp_, mm = model(), model()
    if j is None:
        mp_[name][k] = old + eps; mm[name][k] = old - eps
        new = out[name][k]
    else:
        mp_[name][k][j] = old + eps; mm[name][k][j] = old - eps
        new = out[name][k][j]
    num = (loss_for(mp_) - loss_for(mm)) / (2 * eps)
    delta = old - new
    if abs(num) > 1e-5:
        ratios.append((delta / (0.1 * num), name, k, j, num, delta))

fac = sum(r[0] for r in ratios) / len(ratios)
print("shared 0.1*scale factor =", fac, " (1.0 = unclipped)")
worst = 0.0
for ratio, name, k, j, num, delta in ratios:
    err = abs(ratio - fac) / max(1.0, fac)
    worst = max(worst, err)
assert worst < 1e-4, worst
assert fac <= 1.0 + 1e-9 and fac > 0
print("finite-difference OK across", len(ratios), "nonzero grads; clip scale =", fac)

